import java.util.*;

class Solution {
    public int findMaximum(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            boolean isMaximum = true;

            for (int j = 0; j < nums.length; j++) {
                if (nums[j] > nums[i]) {
                    isMaximum = false;
                    break;
                }
            }

            if (isMaximum) {
                return nums[i];
            }
        }

        return nums[0];
    }
}
